// All editorial decisions come from the immutable canonical catalog.
function cultivationDecision(c){return CATALOG.planning[c.id].audit}
function activeCultivation(c,r){return !!CATALOG.planning[c.id].routes[r]?.active}
const auditedRatingAnalysis=ratingAnalysis;
ratingAnalysis=function(c){const a=auditedRatingAnalysis(c),v=cultivationDecision(c);return {...a,investment:v.investment,limits:a.limits.replace('各可入队线的招募或任务窗口较晚，先用开局角色过渡。','')};};
const auditedCareerRationale=careerRationale;
careerRationale=function(cl,c,context={}){const out=auditedCareerRationale(cl,c,context),a=cultivationDecision(c),reason=a.classReasons[cl.cn],r=routeContext(c),v=CATALOG.planning[c.id].routes[r],direction=a.directions.find(x=>x.route===r),primary=context.label==='主选';
 if(reason)out.why=reason.why+(primary?'':' 可选副职不要求与主选一起练满，只有其属性、武器或熟练能补实际缺项时使用。');
 if(direction&&primary)out.why=direction.reason+' '+out.why;
 out.decision=(direction?.stop||reason?.stop||a.investment)+' '+(context.stage===3?'终局须核对当前职业允许的武器／魔术，已学能力不等于当前能用。':'');
 if(v&&!v.active)out.decision='本线不默认投入另一份同类培养；如本线缺该职责，可沿主养方案临时使用。';
 if((cl.cn==='土匪'||cl.cn==='勇士')&&/剑|枪|拳|物理|格斗/.test(a.role))out.decision='物理伤害、攻速与必要生存达标后停；力量抵消重量后仍可能继续提高每击伤害。';
 return out;
};
function cultivationDecisionPanel(c){const a=cultivationDecision(c),r=routeContext(c),v=CATALOG.planning[c.id].routes[r],dir=a.directions.find(x=>x.route===r);return `<section class="cultivation-decision" aria-label="终局培养结论"><div class="cultivation-decision-head"><div><h3>${esc(a.role)}</h3><small class="heading-meta">终局有效成果</small></div><span class="direction-count">${esc(a.defaultDirections)}<small>方向建议</small></span></div><p>${esc(a.investment)}</p><div class="cultivation-metrics">${[['伤害',a.success.damage],['攻速',a.success.speed],['生存',a.success.survival],['能力',a.success.skills]].map(([n,t])=>`<div><b>${n}</b><span>${esc(t)}</span></div>`).join('')}</div>${dir?`<div class="direction-decision"><span class="stage-label">${esc(dir.level)}</span><b>${esc(dir.label)}</b><p>${esc(dir.condition)}</p></div>`:v&&!v.active?'<div class="direction-decision"><b>本线不重复投入</b><p>可招募不等于需要专门培养。没有新的属性或有效能力成果，默认沿用已完成的主养；本线缺职责时仍可临时使用。</p></div>':''}</section>`;}
const auditedCareerDiagram=careerDiagram;
careerDiagram=function(c){const v=CATALOG.planning[c.id].routes[routeContext(c)];return cultivationDecisionPanel(c)+(v&&!v.active?'':auditedCareerDiagram(c))+careerAlternativesPanel(c);};
trainingProfiles=function(c){return Object.fromEntries(cultivationDecision(c).directions.map(dir=>{const ed=editorRule(c,dir.route);return [dir.route,{...ed,kind:dir.type,optional:dir.level!=='主养',label:dir.label,stop:dir.stop}]}));};
routeSupplements=function(){return route==='救世篇'?[]:DB.characters.filter(c=>isPreferred(c)&&isSupplement(c,route)&&activeCultivation(c,route)&&!routeCandidates().some(x=>x.id===c.id)).sort((a,b)=>routeCost(a,route)-routeCost(b,route));};
routeProfileTable=function(c){const a=cultivationDecision(c),rs=Object.keys(CATALOG.planning[c.id].routes);return (rs.length?`<div class="table-wrap"><table class="profile-table"><thead><tr><th>路线 / 入队门槛</th><th>培养成果与职业</th><th>启用理由 / 停止条件</th></tr></thead><tbody>${rs.map(r=>{const dir=a.directions.find(x=>x.route===r),b=buildPlan(c,r);return `<tr><td>${routeIdentity(r)}<small>${esc(joinTextFor(c,r))}</small></td><td>${dir?`<span class="stage-label">${esc(dir.level)}</span><b>${esc(dir.label)}</b><small>${complementStages(c,b)}</small>`:'<span class="muted">不重复投入</span>'}</td><td>${dir?`${esc(dir.reason)}<small>${esc(dir.stop)}</small>`:'可招募，但默认没有需要新增的独立培养成果；本线缺职责时可临时使用。'}</td></tr>`}).join('')}</tbody></table></div>`:'')+`<div class="fusion-result">${tag('终局职责')}<b>${esc(finalBuild(c).end)}</b><p>${esc(a.investment)}</p><small>${esc(CATALOG.crossRoutePolicy.fusion)}</small></div>`;};
preferencePlan=function(){const chosen=DB.characters.filter(c=>isPreferred(c)&&Object.keys(CATALOG.planning[c.id].routes).length);return `<h2>跨线互补培养 · 主养与补修分开</h2>${crossRoutePolicyPanel()}<p class="muted">先看终局用途，再选择一至两个有效方向。条件补养不是必须满级，未分配路线不重复投入；同技能EXP取最高。</p><div class="table-wrap"><table><thead><tr><th>角色 / 方向建议</th>${Object.entries(routes).filter(([r])=>r!=='救世篇').map(([r,n])=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${chosen.map(c=>`<tr><td>${tableCharacter(c,{subtitle:cultivationDecision(c).defaultDirections+'方向 · '+cultivationDecision(c).role})}</td>${Object.keys(routes).filter(r=>r!=='救世篇').map(r=>{const p=trainingProfiles(c)[r],b=buildPlan(c,r);return `<td>${p?`<span class="stage-label">${p.optional?'条件补养':'主养'}</span><b>${esc(p.label)}</b><small>${complementStages(c,b)}</small><small>${esc(p.stop)}</small>`:firstPartHere(c,r)?'<span class="muted">不重复投入</span>':'—'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>${note('出现章不等于实际招募章。声望、入队等级与剩余升级空间共同决定收益；永久属性需实际升级，同技能经验不累加，终局仍是一名角色。')}`;};
casterSupplementGuide=function(c){if(!/魔法|治疗|法术/.test(c.role))return '';return `<section class="caster-supplement"><h3>法系补养：区分物理伤害与负重</h3><div class="table-wrap"><table><thead><tr><th>终局用途</th><th>力量是否需要</th><th>停止条件</th></tr></thead><tbody><tr><td>纯治疗／辅助</td><td>攻速不会追加治疗；不为治疗次数补力量，先完成法术与安全</td><td>功能与生存够用即可</td></tr><tr><td>法术／魔法战技攻击</td><td>魔力服务伤害；力量按实际装备负重补</td><td>目标法术伤害与攻速达标</td></tr><tr><td>兼任物理武器</td><td>力量同时服务每击伤害与负重</td><td>伤害和攻速共同达标，不止看体格</td></tr></tbody></table></div></section>`;};
// The recommendation UI must obey the selected career, not merely character affinities.
const auditedRecommendations=recommendations;
recommendations=function(c){const out=auditedRecommendations(c),cl=classBy(out.className),allowed=new Set(cl?.allowedSkills||[]),weaponSkill={剑:'剑术',枪:'枪术',斧:'斧术',弓:'弓术',拳:'格斗术',手甲:'格斗术'},dances=['舞者','神乐神将'].includes(cl?.cn);let arts=out.arts.filter(a=>a.name!=='跳舞'&&((!a.skill&&!a.weapon)||a.skill==='指挥术'||allowed.has(weaponSkill[a.weapon]||a.skill)));const fixedSkills=characterFixedSkills(c,cl),fixedActions=dances?[{name:'跳舞',description:'使友军再次行动；当前职业提供，不占普通战技槽。',skill:cl.cn,rank:'职业行动',slotCost:0}]:[],blazeArts=(LEARNING?.[c.id]?.combatArts||[]).filter(a=>a.weapon==='圣焰'),fixedNames=new Set(fixedSkills.map(s=>s.name));return {...out,arts,fixedSkills,fixedActions,blazeArts,skills:out.skills.filter(a=>!fixedNames.has(a.name)).filter(a=>!(/白魔法.*装备|装备.*白魔法/.test(a.description||'')&&!allowed.has('白魔术'))&&!(/黑魔法.*装备|装备.*黑魔法/.test(a.description||'')&&!allowed.has('黑魔术'))),magic:out.magic.filter(a=>allowed.has(a.skill||(/白/.test(a.type||'')?'白魔术':'黑魔术')))};};
const auditedEquipmentEntries=equipmentEntries;
equipmentEntries=function(cs,allOptions=false){if(allOptions)return auditedEquipmentEntries(cs,true);const result=new Map();for(const c of cs){const b=buildPlan(c),r=routeContext(c),cl=classBy(r==='summary'?b.end.split(' / ')[0]:b.upper[0]),allowed=new Set(cl?.allowedSkills||[]);let ids=auditedEquipmentEntries([c]).map(x=>x.e.id);if(['c11','c49','c57'].includes(c.id)&&r==='summary')ids=['aurora_lance','heal'];if(c.id==='c47'&&r==='summary')ids=['daminasword','damina_bow'];if(c.id==='c31'&&allowed.has('剑术')&&allowed.has('黑魔术'))ids=[...new Set([...ids,'thunder'])];for(const id of ids){const e=EQUIPMENT.find(e=>e.id===id);if(!e)continue;const required={剑:'剑术',枪:'枪术',斧:'斧术',弓:'弓术',拳:'格斗术',手甲:'格斗术'}[e.type];if(required&&!allowed.has(required))continue;if(!result.has(id))result.set(id,{e,users:[]});result.get(id).users.push(c)}}return [...result.values()];};

function careerPathLinks(plan){const groups=plan.groups||plan.classes.map(n=>[n]);return groups.map(group=>group.map(n=>`<button class="text-button" data-reference-type="class" data-reference-id="${esc(classBy(n).id)}">${esc(n)}</button>`).join('<span class="career-path-or">或</span>')).join('<span class="career-path-arrow" aria-label="然后">→</span>');}
function careerAlternativesPanel(c){const plans=CATALOG.careerAlternatives?.[c.id]||[];if(!plans.length)return '';return `<section class="career-alternatives" aria-label="${esc(c.cn)}的备选路线"><h3>备选路线</h3>${plans.map(p=>`<details><summary>${esc(p.title)}</summary><div class="career-path">${careerPathLinks(p)}</div><p>${esc(p.when)}</p><p class="muted">${esc(p.stop)}</p><dl class="branch-requirements">${[...new Set(p.classes)].map(n=>{const cl=classBy(n);return `<div><dt>${esc(n)}</dt><dd>${requirement(cl)}${cl.col_41?' · '+esc(cl.col_41):''}${cl.unlock?'<small>'+esc(cl.unlock)+'</small>':''}</dd></div>`}).join('')}</dl><a class="branch-source" href="${esc(p.source)}" target="_blank" rel="noopener">${/bilibili/.test(p.source)?'视频依据':'攻略站依据'} ↗</a>${p.sourceLabel&&!/bilibili/.test(p.source)?`<small class="muted">${esc(p.sourceLabel)}</small>`:''}</details>`).join('')}</section>`;}
function dancerPlanningPanel(){const g=CATALOG.dancerGuide;if(!g)return '';return `<section class="dancer-planning" aria-label="再行动角色分工"><h2>${esc(g.title)}</h2><p>${esc(g.summary)}</p><div class="dancer-candidates">${g.candidates.map(p=>{const c=DB.characters.find(c=>c.id===p.id);return `<article>${tableCharacter(c,{subtitle:'再行动候选'})}<div class="dancer-plan-body"><div class="career-path">${careerPathLinks(p)}</div><p>${esc(p.when)}</p><small>${esc(p.cost)}</small></div></article>`}).join('')}</div><details><summary>转职条件与分工限制</summary><ul>${g.rules.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><a class="branch-source" href="${esc(g.source)}" target="_blank" rel="noopener">作者的舞位分工 ↗</a></details></section>`;}
const reviewedPreferencePlan=preferencePlan;
preferencePlan=function(){return dancerPlanningPanel()+reviewedPreferencePlan();};
const reviewedThirdPartPlanning=thirdPartPlanning;
thirdPartPlanning=function(){return dancerPlanningPanel()+reviewedThirdPartPlanning();};
const reviewedSources=sources;
sources=function(){return reviewedSources()+`<section class="video-review-source"><h2>全角色视频复审</h2><p>${link(CATALOG.sources.biliCharacterReview[1],CATALOG.sources.biliCharacterReview[0])}</p><p>视频观点用于职责分析与培养建议；技能效果与职业权限采用资料库的统一记录。</p></section>`;};
